# ENGR 391 (Numerical Methods, Dr. Wuthrich, Fall 2026) — theory bank. Final covers Lessons 1–4 and 6–8 (not Lesson 5, ML).
C = "engr391"
L = lambda n, t: f"Lesson {n} – {t}"
Q = []
def mcq(id, topic, q, choices, ans, exp, src): Q.append(dict(id=f"e391-{id}", course=C, topic=topic, type="mcq", question=q, choices=choices, answer=ans, explanation=exp, source=src))
def tf(id, topic, q, ans, exp, src): Q.append(dict(id=f"e391-{id}", course=C, topic=topic, type="tf", question=q, answer=ans, explanation=exp, source=src))
def sa(id, topic, q, ans, exp, src, kw=()): Q.append(dict(id=f"e391-{id}", course=C, topic=topic, type="short", question=q, answer=ans, explanation=exp, source=src, keywords=list(kw)))

T = "Errors & fundamentals"; s = L(1, "Introduction and Fundamentals")
sa("er-01", T, "Name the two kinds of numerical error discussed in Lesson 1 and where each comes from.", "Round-off error: the computer stores only a finite number of digits. Truncation error: an infinite process (e.g. a Taylor series or a limit) is cut off after finitely many steps.", "Other error sources (modelling, bad input data) exist but aren't the algorithm's fault.", s, ["round-off: finite digits", "truncation: approximation of math"])
tf("er-02", T, "Making the step size $h$ smaller always reduces the total numerical error.", False, "Truncation error falls as $h$ shrinks, but round-off error grows (e.g. subtracting nearly equal numbers). The total error has a minimum at an optimal $h$.", s)
mcq("er-03", T, "A truncation error of $O(h^2)$ means that halving $h$ reduces the error by roughly a factor of:", ["4", "2", "8", "16"], 0, "$(1/2)^2=1/4$. For $O(h^4)$ the factor is 16.", s)
mcq("er-04", T, "Truncating a Taylor series after the $h^n$ term leaves a remainder of order:", ["$O(h^{n+1})$", "$O(h^n)$", "$O(h^{n-1})$", "$O(1)$"], 0, "The remainder is $\\frac{f^{(n+1)}(\\xi)}{(n+1)!}h^{n+1}$.", s)
tf("er-05", T, "The true error needs the exact answer, so in practice algorithms use an estimated error (e.g. the change between successive iterates) to decide when to stop.", True, "Example: stop when $|x_{i+1}-x_i|<$ TOL.", s)
mcq("er-06", T, "Subtracting two nearly equal floating-point numbers mainly causes:", ["Loss of significant digits (catastrophic cancellation)", "Overflow", "Truncation error", "No error at all"], 0, "This is why forward-difference derivatives go bad when $h$ is tiny.", L(6, "Numerical Differentiation"))

T = "Nonlinear equations"; s = L(2, "Non-linear Equations")
mcq("nl-01", T, "Which two root-finding methods are bracketing methods?", ["Bisection and false position", "Newton and fixed-point", "Newton and secant", "Fixed-point and bisection"], 0, "Bracketing needs $f(a)f(b)<0$ and always converges. Open methods (fixed-point, Newton) may not converge.", s)
tf("nl-02", T, "Bisection is guaranteed to converge for a continuous $f$ with $f(a)f(b)<0$.", True, "By the intermediate value theorem there's a root in $[a,b]$, and each step halves the bracket.", s)
mcq("nl-03", T, "After $n$ bisection steps starting from $[a,b]$, the error bound (using the midpoint) is:", ["$\\dfrac{b-a}{2^{n+1}}$", "$\\dfrac{b-a}{n}$", "$(b-a)^n$", "$\\dfrac{b-a}{2n}$"], 0, "Solve this for $n$ to find how many steps reach a given TOL.", s)
mcq("nl-04", T, "Bisection converges:", ["Linearly, with ratio 1/2", "Quadratically", "Superlinearly", "Cubically"], 0, "Each step gains about one binary digit (~0.3 decimal digits).", s)
mcq("nl-05", T, "The fixed-point iteration $x_{i+1}=g(x_i)$ converges locally to the fixed point $r$ if:", ["$|g'(r)|<1$", "$|g'(r)|>1$", "$g(r)=0$", "$g'(r)=1$"], 0, "The convergence is linear with rate $S=|g'(r)|$. If $|g'(r)|>1$ the iteration diverges.", s)
tf("nl-06", T, "The same equation $f(x)=0$ can be rewritten as $x=g(x)$ in several ways, and some rewritings converge while others diverge.", True, "Pick a $g$ with $|g'(r)|<1$, and as small as possible.", s)
mcq("nl-07", T, "Newton's method update is:", ["$x_{i+1}=x_i-\\dfrac{f(x_i)}{f'(x_i)}$", "$x_{i+1}=x_i-f'(x_i)f(x_i)$", "$x_{i+1}=\\dfrac{x_i+f(x_i)}{2}$", "$x_{i+1}=g(x_i)$ with $g=f$"], 0, "Geometrically: follow the tangent line down to the $x$-axis.", s)
mcq("nl-08", T, "Newton's method at a root of multiplicity $m>1$ converges:", ["Only linearly, with rate $(m-1)/m$", "Quadratically", "Cubically", "Not at all"], 0, "Quadratic convergence needs a simple root ($f'(r)\\ne0$). The modified Newton $x_{i+1}=x_i-m\\,f/f'$ restores it.", s)
tf("nl-09", T, "Newton's method always converges, whatever the initial guess.", False, "It's an open method. A poor guess, a near-zero $f'$ or cycling can make it diverge.", s)
mcq("nl-10", T, "The backward error of an approximate root $x_a$ is:", ["$|f(x_a)|$", "$|r-x_a|$", "$|x_a|$", "$|f'(x_a)|$"], 0, "The forward error is $|r-x_a|$. A small backward error does not guarantee a small forward error when the problem is ill-conditioned.", s)
sa("nl-11", T, "Why are multiple roots ill-conditioned?", "Near a root of multiplicity $m$, $f$ is very flat ($f'(r)=0$), so a tiny backward error $|f(x_a)|$ allows a large forward error $|r-x_a|\\approx(m!|f(x_a)|/|f^{(m)}|)^{1/m}$. Small changes to the equation shift the root a lot.", "The error magnification factor is large. This is the Wilkinson polynomial idea.", s, ["flat f", "small backward, large forward", "error magnification"])
mcq("nl-12", T, "The error magnification factor is:", ["Relative forward error ÷ relative backward error", "Forward error × backward error", "Backward error ÷ forward error", "Number of iterations ÷ tolerance"], 0, "A large factor means the problem is ill-conditioned.", s)
mcq("nl-13", T, "An algorithm converges with order $q$ if:", ["$e_{i+1}\\approx C\\,e_i^q$", "$e_{i+1}\\approx C\\,q\\,e_i$", "$e_{i+1}=e_i-q$", "$e_i\\approx q^i$"], 0, "$q=1$ linear (needs $C<1$), $q=2$ quadratic (correct digits roughly double each step).", s)

T = "Linear systems"; s = L(3, "Linear Equations")
tf("ls-01", T, "Gauss elimination and LU decomposition have no truncation error. Only round-off error affects the result.", True, "They are direct methods that would be exact in exact arithmetic. (L3 takeaway)", s)
sa("ls-02", T, "What are the two stages of Gauss elimination?", "Forward elimination (reduce the augmented matrix to upper-triangular form), then back substitution (solve from the last equation upward).", "Forward elimination costs about $\\tfrac23n^3$ operations. Back substitution costs about $n^2$.", s, ["forward elimination", "back substitution"])
mcq("ls-03", T, "Partial pivoting means:", ["Swapping rows so the pivot is the largest-magnitude entry in its column (at or below the diagonal)", "Swapping columns randomly", "Dividing every row by its largest entry", "Skipping zero pivots"], 0, "It avoids dividing by zero or tiny pivots, which would amplify round-off.", s)
tf("ls-04", T, "Naive Gauss elimination can fail even when the system has a unique solution.", True, "For example, with a zero pivot $a_{11}=0$. Pivoting fixes this.", s)
mcq("ls-05", T, "The main advantage of LU decomposition over plain Gauss elimination is:", ["Once $A=LU$ is computed, each new right-hand side $b$ is solved cheaply (two triangular solves)", "It has no round-off error", "It works for singular matrices", "It needs no pivoting ever"], 0, "Solve $Lc=b$ (forward), then $Ux=c$ (back). Each costs only $O(n^2)$.", s)
mcq("ls-06", T, "With pivoting, the factorization is written as:", ["$PA=LU$, with $P$ a permutation matrix", "$A=LUP$", "$A=PLU^T$", "$A=L+U$"], 0, "Then $Ax=b$ becomes $LUx=Pb$.", s)
mcq("ls-07", T, "The infinity norm $\\|x\\|_\\infty$ of a vector is:", ["$\\max_i|x_i|$", "$\\sum|x_i|$", "$\\sqrt{\\sum x_i^2}$", "$\\min_i|x_i|$"], 0, "The matching matrix norm $\\|A\\|_\\infty$ is the maximum absolute row sum.", s)
mcq("ls-08", T, "The condition number $\\mathrm{cond}(A)=\\|A\\|\\|A^{-1}\\|$ represents:", ["The largest possible error magnification factor when solving $Ax=b$", "The number of iterations needed", "The determinant of $A$", "The rank of $A$"], 0, "$\\mathrm{cond}(A)\\ge1$. A large value means ill-conditioned.", s)
mcq("ls-09", T, "If $\\mathrm{cond}(A)\\approx10^k$, you can expect to lose about ___ significant digits when solving $Ax=b$:", ["$k$", "$2k$", "$k/2$", "$10^k$"], 0, "With double precision (~16 digits) and $\\mathrm{cond}=10^{10}$, only about 6 digits are trustworthy.", s)
tf("ls-10", T, "A small residual $\\|b-Ax_a\\|$ guarantees that $x_a$ is close to the true solution.", False, "The residual is the backward error. If $A$ is ill-conditioned, the forward error can be large despite a small residual.", s)
tf("ls-11", T, "A system with two nearly identical equations (nearly parallel lines) is ill-conditioned.", True, "Tiny changes in the data move the intersection point a lot.", s)

T = "Regression & interpolation"; s = L(4, "Regression and Interpolation")
sa("ri-01", T, "What is the difference between regression and interpolation?", "Regression (curve fitting) finds a model that best fits noisy data in the least-squares sense and need not pass through the points. Interpolation finds a function that passes exactly through every data point.", "Use regression for measured data with scatter, interpolation for exact tabulated values.", s, ["regression: best fit, least squares", "interpolation: passes through points"])
mcq("ri-02", T, "Linear least squares chooses parameters to minimize:", ["The squared error $SE=\\sum r_i^2$", "The largest residual", "The sum of residuals $\\sum r_i$", "The number of data points"], 0, "Setting the partial derivatives to zero gives the normal equations $A^TA\\hat a=A^Ty$.", s)
mcq("ri-03", T, "The root-mean-square error of a fit is:", ["$\\sqrt{SE/m}$", "$SE/m$", "$\\sqrt{SE}$", "$SE\\cdot m$"], 0, "MSE $=SE/m$, RMSE $=\\sqrt{MSE}$, with $m$ = number of data points.", s)
tf("ri-04", T, "\"Linear\" regression means linear in the parameters $a_i$, so $y=a_1+a_2x+a_3x^2$ or $y=a_1+a_2\\sin x$ count as linear models.", True, "The basis functions $f_i(x)$ can be nonlinear in $x$.", s)
mcq("ri-05", T, "To fit an exponential model $y=c\\,e^{kx}$ with linear least squares, you:", ["Take logs: $\\ln y=\\ln c+kx$, then fit a line", "Fit $y$ directly against $x$", "Take $\\sqrt y$", "Use interpolation instead"], 0, "Power law $y=cx^k$: $\\ln y=\\ln c+k\\ln x$. This is linearization (e.g. the Moore's law example).", s)
tf("ri-06", T, "The residual vector of a least-squares fit is orthogonal to the columns of $A$.", True, "$A^T(y-A\\hat a)=0$ is exactly the normal equations.", s)
mcq("ri-07", T, "Through $n$ distinct data points there is a unique interpolating polynomial of degree at most:", ["$n-1$", "$n$", "$n+1$", "$2n$"], 0, "Vandermonde, Newton and Lagrange forms all give the same polynomial, written differently.", s)
tf("ri-08", T, "The Vandermonde matrix is often badly conditioned, which is one reason to prefer the Newton or Lagrange forms.", True, "Its columns $1,x,x^2,\\dots$ become nearly parallel.", s)
mcq("ri-09", T, "A practical advantage of Newton's divided-difference form is:", ["Adding a new data point only adds one new term, so earlier coefficients are reused", "It needs no arithmetic", "It always gives a lower-degree polynomial", "It avoids round-off completely"], 0, "Coefficients come from the top diagonal of the divided-difference table.", s)
sa("ri-10", T, "What does the interpolation error theorem say, and how can the error be reduced?", "$f(x)-P(x)=\\frac{(x-x_1)\\cdots(x-x_n)}{n!}f^{(n)}(c)$. The error depends on the product of distances to the nodes and on a high derivative. It can be reduced by placing nodes well, e.g. Chebyshev points clustered toward the ends rather than equally spaced.", "Equally spaced high-degree interpolation can oscillate wildly near the ends (Runge phenomenon).", s, ["product (x−xi)", "f^(n)/n!", "Chebyshev nodes", "Runge"])
tf("ri-11", T, "Increasing the degree of an equally spaced interpolating polynomial always improves accuracy.", False, "The Runge phenomenon: large oscillations near the interval ends.", s)
mcq("ri-12", T, "Cubic splines join piecewise cubics so that at interior knots these are continuous:", ["The function, first and second derivatives", "Only the function", "The function and first derivative only", "All derivatives"], 0, "End conditions (natural, clamped, …) supply the last two equations.", s)

T = "Numerical differentiation"; s = L(6, "Numerical Differentiation")
mcq("nd-01", T, "The forward difference $\\dfrac{f(x+h)-f(x)}{h}$ has truncation error:", ["$O(h)$", "$O(h^2)$", "$O(h^3)$", "$O(1)$"], 0, "The central difference $\\frac{f(x+h)-f(x-h)}{2h}$ is $O(h^2)$.", s)
mcq("nd-02", T, "The three-point central difference for $f''(x)$ is:", ["$\\dfrac{f(x+h)-2f(x)+f(x-h)}{h^2}$, error $O(h^2)$", "$\\dfrac{f(x+h)-f(x-h)}{2h}$", "$\\dfrac{f(x+h)-2f(x)}{h^2}$", "$\\dfrac{f(x+2h)-f(x)}{2h}$"], 0, "This comes from adding the Taylor series for $f(x\\pm h)$.", s)
sa("nd-03", T, "Why is there an optimal step size $h$ for numerical differentiation?", "Total error = truncation error (shrinks as $h$ shrinks, e.g. $\\propto h^2$) + round-off error (grows like $\\epsilon_{mach}/h$ because of cancellation). Their sum has a minimum at an intermediate $h$.", "For the central difference, $h_{opt}\\sim\\epsilon_{mach}^{1/3}\\approx10^{-5}$ in double precision.", s, ["truncation decreases", "round-off increases", "minimum total"])
tf("nd-04", T, "Higher-order difference formulas allow a larger optimal $h$ and a smaller minimum achievable error.", True, "Their truncation error drops faster, so round-off dominates later.", s)

T = "Numerical integration"; s = L(7, "Numerical Integration")
mcq("ni-01", T, "Newton–Cotes formulas are derived by:", ["Integrating an interpolating polynomial through equally spaced points", "Choosing optimal (non-uniform) nodes", "Fitting a least-squares line", "Taylor series in $h$ only"], 0, "Closed formulas include the endpoints (trapezoid, Simpson). Open formulas don't (midpoint).", s)
mcq("ni-02", T, "The composite trapezoid rule has global error:", ["$O(h^2)$", "$O(h)$", "$O(h^3)$", "$O(h^4)$"], 0, "A single application has error $-\\frac{h^3}{12}f''(c)$. Summing $n\\propto1/h$ panels loses one order.", s)
mcq("ni-03", T, "The composite Simpson's 1/3 rule has global error:", ["$O(h^4)$", "$O(h^2)$", "$O(h^3)$", "$O(h^5)$"], 0, "Halving $h$ cuts the error by about 16. It needs an even number of subintervals.", s)
mcq("ni-04", T, "The degree of precision of Simpson's rule is:", ["3", "2", "1", "4"], 0, "Degree of precision = highest polynomial degree integrated exactly. Trapezoid: 1. Simpson: 3 (one more than expected).", s)
tf("ni-05", T, "Composite Simpson's rule requires an even number of subintervals.", True, "Each application covers two subintervals (three points).", s)
mcq("ni-06", T, "When $h$ is halved, the error of the composite trapezoid rule falls by about a factor of:", ["4", "2", "8", "16"], 0, "Ratios close to 4 (trapezoid) or 16 (Simpson) confirm the expected order of convergence.", s)
sa("ni-07", T, "What is Richardson extrapolation (the Richardson error formula) used for in numerical integration?", "Combining two estimates with step sizes $h$ and $h/2$ to estimate the error and cancel the leading error term. For an $O(h^n)$ method: error $\\approx\\frac{I_{h/2}-I_h}{2^n-1}$, and the improved value is $I_{h/2}+\\frac{I_{h/2}-I_h}{2^n-1}$.", "Applying it repeatedly to the trapezoid rule gives Romberg integration.", s, ["two step sizes", "estimate error", "cancel leading term", "Romberg"])
mcq("ni-08", T, "Romberg integration is:", ["Repeated Richardson extrapolation of composite trapezoid estimates", "Gauss quadrature with random nodes", "Simpson's 3/8 rule", "Monte Carlo integration"], 0, "Each column of the Romberg table raises the order by 2.", s)
mcq("ni-09", T, "Gauss quadrature with $n$ points is exact for polynomials up to degree:", ["$2n-1$", "$n-1$", "$n$", "$2n$"], 0, "It achieves this by choosing both the node locations and the weights optimally (roots of Legendre polynomials).", s)
tf("ni-10", T, "Gauss quadrature needs the function values at non-uniformly spaced points, so it suits integrating a known function better than tabulated equally spaced data.", True, "For tabulated data, use composite Newton–Cotes formulas.", s)

T = "Initial value problems"; s = L(8, "Initial Value Problems")
mcq("iv-01", T, "Euler's method update for $y'=f(t,y)$ is:", ["$w_{i+1}=w_i+h\\,f(t_i,w_i)$", "$w_{i+1}=w_i+\\frac h2[f(t_i,w_i)+f(t_{i+1},w_{i+1})]$", "$w_{i+1}=w_i+h\\,f(t_{i+1},w_{i+1})$", "$w_{i+1}=w_i-h\\,f'(t_i)$"], 0, "Explicit, first order. Follow the slope at the start of the step.", s)
mcq("iv-02", T, "Euler's method has local and global truncation errors of order:", ["$O(h^2)$ local, $O(h)$ global", "$O(h)$ local, $O(h^2)$ global", "$O(h^2)$ both", "$O(h^3)$ local, $O(h^2)$ global"], 0, "Errors accumulate over $\\sim1/h$ steps, so the global error is one order lower than the local error.", s)
mcq("iv-03", T, "Classical RK4 has global truncation error:", ["$O(h^4)$", "$O(h^2)$", "$O(h^5)$", "$O(h)$"], 0, "It uses four slope evaluations per step. Local error $O(h^5)$.", s)
mcq("iv-04", T, "The explicit trapezoid method (Heun) and the midpoint method are both:", ["Second-order Runge–Kutta methods", "First-order methods", "Fourth-order methods", "Implicit multistep methods"], 0, "Both use two slope evaluations per step and have global error $O(h^2)$.", s)
sa("iv-05", T, "What is the intuitive idea behind Runge–Kutta methods compared with Euler's method?", "Instead of using only the slope at the start of the step, they evaluate the slope at several points inside the step and use a weighted average. This reaches higher accuracy without needing derivatives of $f$.", "Taylor methods also reach higher order, but they need the derivatives of $f$.", s, ["several slope evaluations", "weighted average", "no derivatives of f"])
sa("iv-06", T, "What does the Lipschitz condition guarantee for an IVP, and what are its consequences?", "If $|f(t,y_1)-f(t,y_2)|\\le L|y_1-y_2|$, the IVP has a unique solution, and solutions starting from nearby initial conditions stay close, separating by at most a factor $e^{L(t-t_0)}$. So small errors can grow over time.", "This explains why the global error can grow exponentially with $t$.", s, ["existence and uniqueness", "e^{L(t−t0)} growth", "sensitivity to ICs"])
tf("iv-07", T, "For a stiff or rapidly decaying problem, Euler's method with too large a step can produce oscillating, growing (unstable) solutions even though the true solution decays.", True, "For $y'=-\\lambda y$, explicit Euler is stable only if $h<2/\\lambda$.", s)
mcq("iv-08", T, "A higher-order ODE like $y''=f(t,y,y')$ is solved with IVP solvers by:", ["Rewriting it as a first-order system: $y_1=y$, $y_2=y'$", "Applying Euler directly to $y''$", "Integrating twice analytically first", "It cannot be solved numerically"], 0, "Pendulum and orbital-mechanics examples in Lesson 8.", s)
tf("iv-09", T, "For very small step sizes, round-off error can make IVP results worse, just as in numerical differentiation.", True, "The total error vs $h$ again has a minimum.", s)
mcq("iv-10", T, "Using Richardson's formula with step sizes $h$ and $h/2$ for an order-$n$ method, the estimated error of the $h/2$ solution is:", ["$\\dfrac{w_{h/2}-w_h}{2^n-1}$", "$w_{h/2}-w_h$", "$\\dfrac{w_h}{2^n}$", "$2^n(w_{h/2}-w_h)$"], 0, "This is the basis for error control and step-size selection.", s)
